// sharedPurchaseDraftWhereR holds the relationship-based filters of
// sharedPurchaseDraftWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type sharedPurchaseDraftWhereR[Q psql.Filterable] struct {
	cols sharedPurchaseDraftColumns
}

// HasHousehold filters parents that have a matching Household using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Households).
func (w sharedPurchaseDraftWhereR[Q]) HasHousehold(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Households.NameExpr()),
		sm.Where(Households.Columns.ID.EQ(w.cols.HouseholdID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *SharedPurchaseDraft) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("sharedPurchaseDraft cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.SharedPurchaseDrafts = SharedPurchaseDraftSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("sharedPurchaseDraft has no relationship %q", name)
	}
}

