// LoadHousehold loads the sharedPurchaseDraft's Household into the .R struct
func (o *SharedPurchaseDraft) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.SharedPurchaseDrafts = SharedPurchaseDraftSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the sharedPurchaseDraft's Household into the .R struct
func (os SharedPurchaseDraftSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	sharedPurchaseDraftByKey := make(map[uuid.UUID][]*SharedPurchaseDraft, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		sharedPurchaseDraftByKey[o.HouseholdID] = append(sharedPurchaseDraftByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := sharedPurchaseDraftByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.SharedPurchaseDrafts = append(rel.R.SharedPurchaseDrafts, o)

			o.R.Household = rel

		}
	}

	return nil
}

type sharedPurchaseDraftJoins[Q dialect.Joinable] struct {
	typ       string
	Household modAs[Q, householdColumns]
}

func (j sharedPurchaseDraftJoins[Q]) aliasedAs(alias string) sharedPurchaseDraftJoins[Q] {
	return buildSharedPurchaseDraftJoins[Q](buildSharedPurchaseDraftColumns(alias), j.typ)
}

func buildSharedPurchaseDraftJoins[Q dialect.Joinable](cols sharedPurchaseDraftColumns, typ string) sharedPurchaseDraftJoins[Q] {
	return sharedPurchaseDraftJoins[Q]{
		typ: typ,
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
